-- 瑠璃急行線（系統30）のダイヤを組みなおす（2026-10-30。ローカルの写しで組んで、重なり・走れない列車が0になるのを確かめたもの）
--   特急（毎時1本・見晴温泉口〜瑠璃急翠浜）・快速（30分おき・那国高野台〜瑠璃急翠浜）・普通・普通(牧)。停車駅は本人のパターンのまま
--   中心部（麦畑北楓〜夕凪高砂）は、普通が10分おき。普通は決まった駅で少し長く止まり、そこで快速・特急が追いこす
--   本数：快速 62本（編成10）・普通 477本（編成29）・普通(牧) 64本（編成6）・特急 31本（編成5）。運用は種別ごと（運用番号は編成の名前のまま）
--   瑠璃快速•開臨若葉直通線（系統13）：柏木栄・美東中央の番線を走る向きにあわせ（50本）、重なる22本を少しずらす。玖珠線（系統8）：富士見瑠璃越は3・4番線（62本）
--   前のダイヤは、それぞれの系統の「↶ 取り消す」1回でもどせます
--   前提（駅・区間・停車駅のパターン・番線・系統8と13の列車・編成）が変わっていたら、何も変えずに止まります
do $kz$
declare r mp_routes; nm text[] := array['U11','U12','U13','U14','U15','U16','U17','U18','U19','U20','U21','U22','U23','U24','U25','U26','U27','U28','U29','U30','U31','U32','U33','U34','U35','U36','U37','U38','U39','U49','U50','U51','U52','U53','U54','U55','U56','U57','U58','U65','U66','U67','U68','U69','X02','X03','X04','X05','X06','X07']::text[]; nbad int; w text;
begin
  select * into r from mp_routes where id = 30;
  if not found then raise exception '瑠璃急行線（系統30）が見つかりません'; end if;
  if md5(concat_ws('|', r.kind, r.stops::text, r.legs::text, r.pats::text, r.dwell::text)) <> '397f6226c1b56cdaf51a36a6d62eb549' then raise exception '瑠璃急行線の駅・区間・停車駅のパターンが変わっています（何も変えずに止めます）'; end if;
  if (select md5(string_agg(concat_ws(':', s.id, s.tracks, s.plat, _mp_sta_trk(s)::text), ',' order by s.id)) from mp_stations s where s.id = any(r.stops)) <> 'f93864d0af2bd8cb3727ab16bca91e69' then raise exception '瑠璃急行線の駅の番線・ホームが変わっています（何も変えずに止めます）'; end if;
  if (select md5(coalesce(string_agg(concat_ws(':', t.id, t.dir, t.num, t.kind, t.dep, t.tt::text, t.skip::text, t.sa, t.sb, t.form, t.day, t.cpl::text), ',' order by t.id), ''))
            from mp_trains t where t.route = 13) <> '3678c38faab46f159c44f75819ebb59c' then raise exception '瑠璃快速•開臨若葉直通線（系統13）の列車が変わっています（何も変えずに止めます）'; end if;
  if (select md5(coalesce(string_agg(concat_ws(':', t.id, t.dir, t.num, t.kind, t.dep, t.tt::text, t.skip::text, t.sa, t.sb, t.form, t.day, t.cpl::text), ',' order by t.id), ''))
            from mp_trains t where t.route = 8) <> '3a410079e66c1be5281872cca02ba8fb' then raise exception '玖珠線（系統8）の列車が変わっています（何も変えずに止めます）'; end if;
  if (select count(*) from mp_forms f where f.own_u = r.own_u and f.own_c is null and f.name = any(nm)) <> cardinality(nm) then
    raise exception '使う編成（%）が見つからないか、同じ名前が2つあります（何も変えずに止めます）', array_to_string(nm, '・');
  end if;
  if exists (select 1 from mp_trains t join mp_forms f on f.id = t.form where t.route <> 30 and f.own_u = r.own_u and f.own_c is null and f.name = any(nm)) then
    raise exception 'ほかの系統で使っている編成があります（何も変えずに止めます）';
  end if;
  -- 「↶ 取り消す」でもどせるように、前のダイヤをのこす
  perform _mp_dia_snap(30, '更新：ダイヤを組みなおした（特急・快速・普通）');
  perform _mp_dia_snap(13, '更新：瑠璃急行線にあわせて時刻をずらした');
  perform _mp_dia_snap(8, '更新：富士見瑠璃越は3・4番線');
  delete from mp_trains where route = 30;
  insert into mp_trains(route, dir, num, kind, dep, form, op, skip, sa, sb, tt)
  select 30, x.dir, x.num, x.kind, x.dep, f.id, _mp_op_of_form(f.id), x.skip, x.sa, x.sb, x.tt
